static int32_t rd_i32(Rd *r) { return (int32_t)rd_u32(r); }
static uint16_t rd_u16(Rd *r) { if (r->end - r->p < 2) { r->err = 1; return 0; } uint16_t v = (uint16_t)(r->p[0] | r->p[1] << 8); r->p += 2; return v; }
static int16_t rd_i16(Rd *r) { return (int16_t)rd_u16(r); }
static uint8_t rd_u8(Rd *r) { if (r->end - r->p < 1) { r->err = 1; return 0; } return *r->p++; }
static int8_t rd_i8(Rd *r) { return (int8_t)rd_u8(r); }
static float rd_f32(Rd *r) { union { uint32_t u; float f; } c; c.u = rd_u32(r); return c.f; }
static const char *rd_str(Rd *r) { uint32_t o = rd_u32(r); return o == 0xFFFFFFFFU ? NULL : r->pool + o; }

